<?php
require_once 'config.php'; require_login();$page_title='Orders';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';$allowed=['pending','processing','shipped','delivered','cancelled'];if(in_array($status,$allowed,true)){$stmt=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$stmt->execute([$status,$id]);redirect('orders.php?updated=1');}}
$orders=$pdo->query('SELECT o.*,c.name AS customer_name,c.phone FROM orders o LEFT JOIN customers c ON c.id=o.customer_id ORDER BY o.id DESC')->fetchAll();require 'partials/header.php';
?><div class="panel"><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Total</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><b><?=e($o['order_number'])?></b></td><td><?=e($o['customer_name']??'—')?><br><small class="muted"><?=e($o['phone']??'')?></small></td><td><?=e($o['created_at'])?></td><td>₹<?=number_format((float)$o['total'],2)?></td><td><span class="status"><?=e($o['status'])?></span></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$o['id']?>"><select name="status"><?php foreach(['pending','processing','shipped','delivered','cancelled'] as $s):?><option value="<?=$s?>" <?=$o['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn small-btn">Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php if(!$orders):?><p class="empty">No orders recorded yet.</p><?php endif;?></div><?php require 'partials/footer.php';?>
